const body = $json.body;
if (!body || typeof body !== 'object' || Array.isArray(body)) {
  return [{ json: { kind: 'invalid', violations: ['invalid-risk-request'] } }];
}
const parent = body.parent && typeof body.parent === 'object' ? body.parent : {};
return [{ json: {
  ...body,
  _workflow: {
    workflowId: 'toss-trader-risk-manager',
    executionId: $execution.id,
    trigger: $execution.mode,
    stage: 'risk-manager-evaluate',
    parentExecutionId: parent.executionId || 'unknown',
    portfolioId: parent.portfolioId || 'unknown',
    interval: parent.interval || 'unknown',
  },
} }];

const input = $json;
const signal = input.signal;
const context = input.context;
const limits = input.limits;
if (!signal || typeof signal !== 'object' || !context || typeof context !== 'object') throw new Error('trade signal/context must be objects');
if (!limits || typeof limits !== 'object' || limits.policyVersion !== 2) throw new Error('unsupported risk policy');
const text = (value, name) => { if (typeof value !== 'string' || value.length === 0) throw new Error(`${name} must be text`); return value; };
const bool = (value, name) => { if (typeof value !== 'boolean') throw new Error(`${name} must be boolean`); return value; };
const integer = (value, name) => { if (!Number.isInteger(value) || value < 0) throw new Error(`${name} must be a non-negative integer`); return value; };
const dec = (value, name) => {
  if (typeof value !== 'string' && typeof value !== 'number') throw new Error(`${name} must be decimal`);
  const match = String(value).match(/^(-?)(\d+)(?:\.(\d+))?$/);
  if (!match) throw new Error(`${name} must be decimal`);
  const fraction = match[3] || '';
  const digits = `${match[1]}${match[2]}${fraction}`;
  return { n: BigInt(digits), s: fraction.length };
};
const pow10 = (value) => 10n ** BigInt(value);
const cmp = (left, right) => { const scale = Math.max(left.s, right.s); const a = left.n * pow10(scale - left.s); const b = right.n * pow10(scale - right.s); return a < b ? -1 : a > b ? 1 : 0; };
const add = (left, right) => { const scale = Math.max(left.s, right.s); return { n: left.n * pow10(scale - left.s) + right.n * pow10(scale - right.s), s: scale }; };
const mul = (left, right) => ({ n: left.n * right.n, s: left.s + right.s });
const maxOrderNotional = dec(limits.maxOrderNotional, 'maxOrderNotional');
const maxPositionNotional = dec(limits.maxPositionNotional, 'maxPositionNotional');
const maxDailyBuyCount = integer(limits.maxDailyBuyCount, 'maxDailyBuyCount');
const maxOpenPositions = integer(limits.maxOpenPositions, 'maxOpenPositions');
const dailyLossLimit = dec(limits.dailyLossLimit, 'dailyLossLimit');
const maxConsecutiveApiErrors = integer(limits.maxConsecutiveApiErrors, 'maxConsecutiveApiErrors');
const closeBlockSeconds = integer(limits.blockNewBuysBeforeCloseSeconds, 'blockNewBuysBeforeCloseSeconds');
const signalId = text(signal.signalId, 'signalId');
text(signal.symbol, 'symbol');
const side = text(signal.side, 'side');
if (side !== 'BUY' && side !== 'SELL') throw new Error('side must be BUY or SELL');
const price = dec(signal.referencePrice, 'referencePrice');
const quantity = dec(signal.quantity, 'quantity');
text(signal.reason, 'reason');
const positionNotional = dec(context.positionNotional, 'positionNotional');
const positionQuantity = dec(context.positionQuantity, 'positionQuantity');
const availableCash = context.availableCash === null || context.availableCash === undefined ? null : dec(context.availableCash, 'availableCash');
const dailyBuyCount = integer(context.dailyBuyCount, 'dailyBuyCount');
const openPositionCount = integer(context.openPositionCount, 'openPositionCount');
const dailyReturnRate = dec(context.dailyReturnRate, 'dailyReturnRate');
const apiErrors = integer(context.consecutiveApiErrors, 'consecutiveApiErrors');
const seenSignalIds = context.seenSignalIds;
if (!Array.isArray(seenSignalIds) || !seenSignalIds.every((value) => typeof value === 'string')) throw new Error('seenSignalIds must be a text list');
const newBuysAllowed = bool(context.newBuysAllowed, 'newBuysAllowed');
const marketIsBusinessDay = bool(context.marketIsBusinessDay, 'marketIsBusinessDay');
const nowText = text(context.now, 'now');
if (!/(Z|[+-]\d{2}:\d{2})$/.test(nowText) || Number.isNaN(Date.parse(nowText))) throw new Error('now must include timezone');
const marketCloseText = context.marketCloseAt;
if (marketCloseText !== null && marketCloseText !== undefined && (typeof marketCloseText !== 'string' || !/(Z|[+-]\d{2}:\d{2})$/.test(marketCloseText) || Number.isNaN(Date.parse(marketCloseText)))) throw new Error('marketCloseAt must include timezone');
const advisorStatus = context.advisorStatus;
if (advisorStatus !== null && advisorStatus !== undefined && typeof advisorStatus !== 'string') throw new Error('advisorStatus must be text');
const advisorRationale = context.advisorRationale;
if (advisorRationale !== null && advisorRationale !== undefined && typeof advisorRationale !== 'string') throw new Error('advisorRationale must be text');
const notional = mul(price, quantity);
const violations = [];
if (seenSignalIds.includes(signalId)) violations.push('duplicate-signal');
if (side === 'BUY' && !newBuysAllowed) violations.push('universe-refresh-failed');
if (advisorStatus === 'rejected') violations.push(`Hermes 거부: ${advisorRationale || '구체적 근거 없음'}`);
else if (advisorStatus === 'unavailable') violations.push('Hermes 분석 실패: 응답을 받지 못해 체결 차단');
if (cmp(notional, maxOrderNotional) > 0) violations.push('max-order-notional');
if (side === 'BUY' && availableCash !== null && cmp(notional, availableCash) > 0) violations.push('insufficient-paper-cash');
if (side === 'BUY' && cmp(add(positionNotional, notional), maxPositionNotional) > 0) violations.push('max-position-notional');
if (side === 'SELL' && cmp(quantity, positionQuantity) > 0) violations.push('insufficient-position');
if (side === 'BUY' && dailyBuyCount >= maxDailyBuyCount) violations.push('max-daily-buys');
if (side === 'BUY' && cmp(positionQuantity, dec('0', 'zero')) <= 0 && openPositionCount >= maxOpenPositions) violations.push('max-open-positions');
if (side === 'BUY' && cmp(dailyReturnRate, dailyLossLimit) <= 0) violations.push('daily-loss-limit');
if (apiErrors >= maxConsecutiveApiErrors) violations.push('api-error-kill-switch');
if (!marketIsBusinessDay) violations.push('market-closed');
if (side === 'BUY' && marketCloseText && Date.parse(nowText) >= Date.parse(marketCloseText) - closeBlockSeconds * 1000) violations.push('market-close-window');
return [{ json: { kind: 'trade', approved: violations.length === 0, violations, _workflow: input._workflow } }];

